package com.smartjobtracker.service;
import com.smartjobtracker.config.GmailConfig; import org.springframework.stereotype.Component; import javax.crypto.Cipher; import javax.crypto.spec.GCMParameterSpec; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.Base64;
@Component public class GmailTokenCipher { private final byte[] key; private final SecureRandom random=new SecureRandom(); public GmailTokenCipher(GmailConfig config){try{key=Base64.getDecoder().decode(config.getEncryptionKey()==null?"":config.getEncryptionKey());}catch(IllegalArgumentException e){throw new IllegalStateException("GMAIL_TOKEN_ENCRYPTION_KEY must be base64",e);} if(key.length!=0&&key.length!=32)throw new IllegalStateException("GMAIL_TOKEN_ENCRYPTION_KEY must be a base64-encoded 32-byte key");} private void requireKey(){if(key.length!=32)throw new IllegalStateException("GMAIL_TOKEN_ENCRYPTION_KEY must be configured before Gmail authorization");} public String encrypt(String value){try{requireKey();byte[] iv=new byte[12];random.nextBytes(iv);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));return Base64.getEncoder().encodeToString(iv)+":"+Base64.getEncoder().encodeToString(cipher.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("Could not encrypt Gmail token",e);}} public String decrypt(String value){try{requireKey();String[] parts=value.split(":",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,Base64.getDecoder().decode(parts[0])));return new String(cipher.doFinal(Base64.getDecoder().decode(parts[1])),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Could not decrypt Gmail token",e);}} }